/**
 * Single source of truth for every scientific statement on the site.
 *
 * Everything here is transcribed from the project's research study
 * ("I am considering developing the following project_.pdf"). That study is a
 * literature review + proposed design: no experiments have been run by the
 * project team yet. Every value therefore carries an evidence tag:
 *
 *   lit       – reported by a cited third-party study / FSSAI / vendor listing
 *   proposed  – part of the project's proposed design (not yet built or tested)
 *   sim       – generated by this website for demonstration only
 *   concept   – illustrative visualization of a mechanism, not measured
 *
 * If you add content, add it here with a tag. Do not add numbers that are not
 * in the research document.
 */

export type Evidence = "lit" | "proposed" | "sim" | "concept";

export const EVIDENCE: Record<Evidence, { label: string; short: string; desc: string }> = {
  lit: {
    label: "Literature value",
    short: "LIT",
    desc: "Reported by a cited third-party study, FSSAI release or vendor listing. Not measured by this project.",
  },
  proposed: {
    label: "Proposed design",
    short: "PROPOSED",
    desc: "Part of the project's planned design. Not yet built or validated.",
  },
  sim: {
    label: "Simulated demonstration",
    short: "SIMULATED",
    desc: "Generated in your browser for illustration. The website does not measure anything.",
  },
  concept: {
    label: "Conceptual visualization",
    short: "CONCEPT",
    desc: "An illustrative picture of a mechanism described in the literature. Not to scale, not measured.",
  },
};

