/** Which nano-scene engine best represents the chemistry. */
export type NanoMode = "agnp" | "aggo" | "starch" | "btb" | "guaiacol" | "dithizone";

export interface Method {
  id: string;
  name: string;
  chemistry: string;
  nanomaterial: string;
  signal: string;
  time: string;
  nanoMode: NanoMode;
  kind: "colorimetric" | "electrochemical";
  /** Color progression used by simulations (illustrative). */
  colorFrom: string;
  colorTo: string;
  lit?: string;
}

export interface Target {
  id: TargetId;
  name: string;
  formula: string;
  food: FoodId;
  foodLabel: string;
  healthConcern: string;
  healthNote: string;
  methods: Method[];
  range: string;
  rangeMin: number;
  rangeMax: number;
  unit: string;
  time: string;
  equipment: string;
  difficulty: string;
  difficultyLevel: number; // 1..5 for meters
  risk: string;
  /** Threshold the simulated verdict is compared against. */
  threshold: { value: number; label: string; kind: "limit" | "lower-bound" };
  /** Typical 'clean' value used when the demo simulates an unadulterated sample. */
  cleanValue: number;
  adulteratedValue: number;
  extra?: string[];
}

